# Completa la línea marcada y compruébala con py check.
import math

def entropia_cruzada(probs, etiquetas):
    total = 0
    for p, y in zip(probs, etiquetas):
        p = min(max(p, 1e-12), 1 - 1e-12)
        total += 0   # ← cambia esta línea: -(y·ln p + (1−y)·ln(1−p))
    return total / len(probs)

print(entropia_cruzada([0.9, 0.2], [1, 0]))   # unos 0.164
